import{_ as s,o as a,c as t,ak as i}from"./chunks/framework.Dpc0wyhY.js";const g=JSON.parse('{"title":"API Notes & Best Practices","description":"","frontmatter":{},"headers":[],"relativePath":"guides/api-notes.md","filePath":"guides/api-notes.md"}'),n={name:"guides/api-notes.md"};function o(r,e,l,d,c,p){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="api-notes-best-practices" tabindex="-1">API Notes &amp; Best Practices <a class="header-anchor" href="#api-notes-best-practices" aria-label="Permalink to “API Notes &amp; Best Practices”">​</a></h1><p>Details of the request layer that are easy to miss and expensive to debug. Read this before writing any provisioning or automation scripts against the REST API.</p><h2 id="send-a-conventional-user-agent" tabindex="-1">Send a Conventional User-Agent <a class="header-anchor" href="#send-a-conventional-user-agent" aria-label="Permalink to “Send a Conventional User-Agent”">​</a></h2><p>Hosted instances sit behind a web application firewall that blocks non-browser automation user agents on <strong>write</strong> requests. Default <code>Python-urllib/*</code>, <code>python-requests/*</code>, and spoofed browser strings get a <code>403 error code: 1010</code>.</p><p>Always send a conventional client user agent:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;User-Agent: curl/8.5.0&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer YOUR_ACCESS_TOKEN&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">     --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://your-domain.com/items/posts&#39;</span></span></code></pre></div><p>GET requests are unaffected — this only bites on POST/PATCH/DELETE.</p><h2 id="url-encode-filter-parameters" tabindex="-1">URL-Encode Filter Parameters <a class="header-anchor" href="#url-encode-filter-parameters" aria-label="Permalink to “URL-Encode Filter Parameters”">​</a></h2><p>Filter parameters with raw brackets intermittently fail through the edge proxy. Always URL-encode them:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Fragile</span></span>
<span class="line"><span>/items/posts?filter[status][_eq]=published</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Reliable</span></span>
<span class="line"><span>/items/posts?filter%5Bstatus%5D%5B_eq%5D=published</span></span></code></pre></div><h2 id="missing-fields-return-403-not-404" tabindex="-1">Missing Fields Return 403, Not 404 <a class="header-anchor" href="#missing-fields-return-403-not-404" aria-label="Permalink to “Missing Fields Return 403, Not 404”">​</a></h2><p><code>GET /fields/{collection}/{missing}</code> returns <code>403 FORBIDDEN</code> rather than <code>404</code>. Do not treat a non-200 response as &quot;doesn&#39;t exist&quot;. For existence checks, list <code>GET /fields/{collection}</code> and search the results — or simply POST and tolerate a <code>400</code>.</p><h2 id="write-effects-are-asynchronous" tabindex="-1">Write Effects Are Asynchronous <a class="header-anchor" href="#write-effects-are-asynchronous" aria-label="Permalink to “Write Effects Are Asynchronous”">​</a></h2><p>Flows triggered by a write run <strong>after</strong> the response is sent. If an <code>items.create</code> flow stamps a serial number, the POST response will show that field as <code>null</code>; the stamped value appears a few seconds later. Always re-fetch an item before verifying derived fields.</p><h2 id="creating-at-a-final-status-skips-update-flows" tabindex="-1">Creating at a Final Status Skips Update Flows <a class="header-anchor" href="#creating-at-a-final-status-skips-update-flows" aria-label="Permalink to “Creating at a Final Status Skips Update Flows”">​</a></h2><p>Flows that trigger on <code>items.update</code> do not run when an item is created directly in its final state — only <code>items.create</code> flows fire. When seeding or importing already-completed records, set the fields those flows would have stamped (timestamps, computed amounts, expiry dates) explicitly in the create payload.</p><h2 id="read-only-is-a-ui-concept" tabindex="-1">&quot;Read Only&quot; Is a UI Concept <a class="header-anchor" href="#read-only-is-a-ui-concept" aria-label="Permalink to “&quot;Read Only&quot; Is a UI Concept”">​</a></h2><p>A field marked <code>readonly</code> in the interface still accepts explicit values over the API with a sufficiently privileged token. This is how seed and migration scripts backdate records — for example, writing historical <code>created_at</code> or completed-at timestamps.</p><h2 id="config-endpoints-do-not-deduplicate" tabindex="-1">Config Endpoints Do Not Deduplicate <a class="header-anchor" href="#config-endpoints-do-not-deduplicate" aria-label="Permalink to “Config Endpoints Do Not Deduplicate”">​</a></h2><p><code>/panels</code>, <code>/dashboards</code>, <code>/flows</code>, and <code>/operations</code> happily create duplicates on repeat POSTs. Always GET-filter by name (and by dashboard, for panels) before creating. Build a chain tail-first: POST operations, then PATCH <code>flow.operation</code> to the first operation&#39;s id.</p><h2 id="never-patch-relations-—-it-can-take-the-server-down" tabindex="-1">Never PATCH Relations — It Can Take the Server Down <a class="header-anchor" href="#never-patch-relations-—-it-can-take-the-server-down" aria-label="Permalink to “Never PATCH Relations — It Can Take the Server Down”">​</a></h2><p><code>PATCH /relations/{collection}/{field}</code> can crash the server process outright on affected versions — a bug in the schema-mutation path exits the process mid-request. This applies to <strong>any</strong> relation PATCH, even a correct, verified payload. <code>POST /relations</code> is safe.</p><p><strong>If your instance went down after a relation PATCH:</strong></p><ul><li><strong>Dev server (nodemon)</strong> — it does <em>not</em> auto-restart; type <code>rs</code> + Enter in its console.</li><li><strong>Docker</strong> — <code>docker compose restart</code> (or <code>up -d</code>) the backend container.</li><li><strong>Hosted</strong> — the platform restarts the process automatically; allow a moment and retry, or contact support if it persists.</li></ul><p><strong>To change relation behavior safely, never PATCH — do one of these instead:</strong></p><ol><li>Delete and recreate the relation with the desired options, or</li><li>Apply the change at the database level through the <a href="/guides/automation-recipes.html#the-sql-query-operation">SQL Query operation</a> and then clear the system schema cache:</li></ol><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --request</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Authorization: Bearer YOUR_ACCESS_TOKEN&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --header</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Content-Type: application/json&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --data</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;cache&quot;:&quot;system&quot;}&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://your-domain.com/utils/cache/clear&#39;</span></span></code></pre></div><h2 id="write-provisioning-scripts-not-one-liners" tabindex="-1">Write Provisioning Scripts, Not One-Liners <a class="header-anchor" href="#write-provisioning-scripts-not-one-liners" aria-label="Permalink to “Write Provisioning Scripts, Not One-Liners”">​</a></h2><p>Two recurring failure modes argue for keeping provisioning logic in script files rather than inline shell commands:</p><ul><li><strong>Shell <code>$</code> expansion corrupts payloads.</strong> <code>curl --data &quot;{...$trigger...}&quot;</code> inside double quotes silently strips <code>$trigger</code>, <code>$last</code>, and <code>$full</code> template tokens — the flow then stores mutilated options and dies silently.</li><li><strong>Encoding.</strong> On Windows, default file encodings corrupt JSON fetched over HTTP (smart quotes become <code>?</code>). Open responses with an explicit <code>utf-8</code> encoding.</li></ul><p>An idempotent Python or Node script — GET, compare, POST/PATCH only what differs — is far more reliable than a pile of curl calls.</p>`,31)])])}const u=s(n,[["render",o]]);export{g as __pageData,u as default};
